 internal static AdapterCounters Adapter(string device){lock(gate){AdapterCounters value;if(!adapters.TryGetValue(device,out value)){if(adapters.Count>=64)return null;adapters[device]=value=new AdapterCounters{Id=adapters.Count+1};}Interlocked.Increment(ref value.Attempts);return value;}}
 internal static void Event(string kind,object value){if(!enabled)return;lock(gate){if(events.Count>=MaxEvents){Interlocked.Increment(ref overflow);return;}events.Enqueue(new{utc=DateTime.UtcNow.ToString("o"),kind,data=value});}}
