 internal static object Ports(Dictionary<int,int> counts){return counts.Select(p=>new{port=p.Key,connections=p.Value}).ToArray();}
 internal static string Clean(string text){if(text==null)return null;foreach(var item in new[]{new[]{Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"%USERPROFILE%"},new[]{Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"%LOCALAPPDATA%"},new[]{root,"%HELPER%"}})if(!string.IsNullOrEmpty(item[0]))text=text.Replace(item[0],item[1]);text=Regex.Replace(text,@"\b(?:\d{1,3}\.){3}\d{1,3}\b","[IPv4]");text=Regex.Replace(text,@"\\Device\\NPF_[^\s:]+","[adapter]");return text.Length<=3000?text:text.Substring(0,3000)+" [truncated]";}
 static object FileInfoFor(string path){try{bool found=File.Exists(path);return new{file=Path.GetFileName(path),exists=found,version=found?FileVersionInfo.GetVersionInfo(path).FileVersion:null,bytes=found?new FileInfo(path).Length:0};}catch(Exception e){return new{file=Path.GetFileName(path),error=Clean(e.Message)};}}
