 internal static void Verify(string directory){string folder=Path.Combine(directory,"diagnostic-fixture");Start(folder);try{Frame(0x008d,10);Frame(0x3336,500);using(var recorder=new Recorder(directory,false))recorder.RefreshFlows();var signal=new DashSignal(directory);var body=new byte[]{0,0x8d,1,1,1,3,0xc0,0x57,1,0};typeof(DashSignal).GetMethod("Decode",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(signal,new object[]{body,0,body.Length,1.0,0,"fixture"});if(signal.Current==null||signal.Current.Value!=88000)throw new Exception("Instrumentation must preserve resource decoding");Decoder(signal.SupportState());var device=Adapter("fixture");device.Opened(1);Interlocked.Increment(ref device.Raw);Interlocked.Increment(ref device.Parsed);Interlocked.Increment(ref device.Owned);Connections(new{processCount=1,connections=1,gamePortConnections=1,remotePorts=Ports(new Dictionary<int,int>{{13328,1},{443,2}})});Decoder(new{synced=true});Overlay(new{samples=2,errors=0,actor=123,fresh=true,status="fixture",secret="DO_NOT_LOG",skillSlots=new{enabled=true,visibleSlots=11,slots=new[]{"DO_NOT_LOG"}}});Event("sanitization",new{message=Clean(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"test.txt")+" 192.0.2.1 "+@"\Device\NPF_{0000}")});for(int i=0;i<400;i++)Event("bounded",new{index=i});Flush(false);device.Closed();Stop();using(var archive=ZipFile.OpenRead(Path.Combine(folder,"support-report.zip"))){if(archive.Entries.Count!=2)throw new Exception("Report must contain only two diagnostic files");foreach(var entry in archive.Entries)using(var reader=new StreamReader(entry.Open())){string text=reader.ReadToEnd();if(text.Contains("DO_NOT_LOG")||text.Contains("192.0.2.1")||text.Contains(@"\Device\NPF_"))throw new Exception("Unapproved data reached the report");}var json=new JavaScriptSerializer();using(var reader=new StreamReader(archive.GetEntry("support-summary.json").Open())){var row=json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());if